package com.lqq.supportflow.action.application;
import com.lqq.supportflow.action.domain.*; import com.lqq.supportflow.eventing.OutboxService; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ManageApprovalService { private final ApprovalPort approvals; private final OutboxService outbox; public ManageApprovalService(ApprovalPort approvals,OutboxService outbox){this.approvals=approvals;this.outbox=outbox;} @Transactional public Approval create(Long tenantId,Long customerId,String actionType,String actionSummary,Long membershipId){return approvals.create(tenantId,customerId,actionType,actionSummary,membershipId);} public List<Approval> list(Long tenantId){return approvals.list(tenantId);} @Transactional public Approval decide(Long tenantId,Long approvalId,Long membershipId,ApprovalStatus decision,String idempotencyKey){ApprovalDecision result=approvals.decide(tenantId,approvalId,membershipId,decision,idempotencyKey);Approval approval=result.approval();if(result.newlyRecorded()&&approval.status()==ApprovalStatus.APPROVED)outbox.record(tenantId,"approval.approved","approval",approval.id().toString(),"{\"approvalId\":"+approval.id()+",\"actionType\":\""+approval.actionType()+"\"}");return approval;}}
